python3 << 'PY'
import json, re
d = json.load(open('/tmp/all_memories.json'))

# Patterns:
date_re = re.compile(r'\b(20\d\d-\d\d-\d\d)\b')
commit_re = re.compile(r'\b([0-9a-f]{8,40})\b')

stats = {
    'has_date': 0,
    'has_commit_hash': 0,
    'mentions_angr_bead': 0,
    'invariant': 0,
    'avoid': 0,
    'benchmark': 0,
    'tiny_lt_100': 0,
    'huge_gt_1500': 0,
}
date_year = {}
for k,v in d.items():
    if date_re.search(v):
        stats['has_date']+=1
        for m in date_re.findall(v):
            y = m[:4]
            date_year[y] = date_year.get(y,0)+1
    if commit_re.search(v):
        stats['has_commit_hash']+=1
    if re.search(r'angr-[a-z0-9]{3,5}\b', v):
        stats['mentions_angr_bead']+=1
    if k.startswith('invariant-'):
        stats['invariant']+=1
    if k.startswith('avoid-'):
        stats['avoid']+=1
    if k.startswith('benchmark-'):
        stats['benchmark']+=1
    if len(v) < 100:
        stats['tiny_lt_100']+=1
    if len(v) > 1500:
        stats['huge_gt_1500']+=1

print('Stats:')
for k,v in stats.items():
    print(f'  {k}: {v}')
print('Year mentions:', dict(sorted(date_year.items())))
PY

