python3 << 'PY'
import json, re
d = json.load(open('/tmp/all_memories.json'))

# Sample bead-id-prefixed memories: do they cluster?
bead_groups = {}
for k in d:
    m = re.match(r'^([0-9a-z]{4,5})-', k)
    if m and m.group(1) not in ['avoid', 'venv', 'bench', 'audit']:
        # Only "looks like" a 4-char bead id (lowercase + digit)
        if re.match(r'^[0-9a-z]{4}$', m.group(1)) or re.match(r'^[a-z][0-9][a-z][0-9]$', m.group(1)):
            bead_groups.setdefault(m.group(1), []).append(k)

multi_bead = {k:v for k,v in bead_groups.items() if len(v) > 1}
print(f'Bead-id prefixes with 2+ memories: {len(multi_bead)}')
for bead, keys in sorted(multi_bead.items(), key=lambda x:-len(x[1]))[:15]:
    print(f'  {bead}: {len(keys)} -> {keys[:3]}...')
PY

python3 << 'PY'
import json, re, subprocess

# Cross-reference memories vs closed beads
mems = json.load(open('/tmp/all_memories.json'))
closed = subprocess.check_output(['bd', 'list', '--status=closed', '--limit=0', '--json'], text=True)
closed_ids = {i['id'] for i in json.loads(closed)}
print(f'Closed beads: {len(closed_ids)}')

# Memories that mention at least one closed bead
ref_re = re.compile(r'\bangr-([a-z0-9]+(?:\.\d+)?)\b')
counts = {'mentions-any-closed':0, 'mentions-only-closed':0, 'mentions-open':0, 'mentions-none':0}
for k,v in mems.items():
    refs = set(ref_re.findall(v))
    refs_full = {f'angr-{r.split(".")[0]}' for r in refs}
    closed_refs = refs_full & closed_ids
    if not refs_full:
        counts['mentions-none']+=1
    else:
        if closed_refs:
            counts['mentions-any-closed']+=1
        if refs_full == closed_refs:
            counts['mentions-only-closed']+=1
        elif refs_full - closed_refs:
            counts['mentions-open']+=1

for k,v in counts.items():
    print(f'  {k}: {v}')
PY

