python3 << 'PY'
import json
d = json.load(open('.bd-prune/snapshot-pre-prune.json'))
# v5a5 likely a real bead. rust/angr/venv are topic prefixes.
# Real bead ID = mix of letters AND digits (heuristic)
import re
def looks_like_bead(p):
    return len(p) == 4 and re.search(r'\d', p) and re.search(r'[a-z]', p)

prefix_groups = {}
for k in d:
    pfx = k.split('-')[0]
    if looks_like_bead(pfx):
        prefix_groups.setdefault(pfx, []).append(k)

# all bead clusters
total_bead_clusters = len(prefix_groups)
big = {k:v for k,v in prefix_groups.items() if len(v)>=5}
print(f'Total real-bead clusters: {total_bead_clusters}')
print(f'Bead-ID clusters with >=5 members: {len(big)}')
for k,v in sorted(big.items(), key=lambda x:-len(x[1])):
    print(f'  {k}: {len(v)} memories  ->', v[:3])
